// Throwaway directory actors holding Better Auth's tables, one per storage
// approach:
//
// - directoryA (approach 1): Better Auth runs on the app node; this actor only
//   runs its storage operations (`store` action, SQL in sql-store.ts). The
//   schema is schema.sql, generated by Better Auth's migration tooling.
// - directoryB (approach 2): Better Auth itself runs inside this actor, on its
//   own Kysely SQLite adapter over c.db (rivet-dialect.ts). The app node
//   forwards /api/auth/* and the OAuth metadata over the actor's raw HTTP
//   handler. Migrations are Better Auth's getMigrations, run in onMigrate.
//
// Both add the two directory reads our own rules need: a user's current
// status (for writes) and marking a user inactive.
import { oauthProviderAuthServerMetadata, oauthProviderOpenIdConfigMetadata } from '@better-auth/oauth-provider'
import { getMigrations } from 'better-auth/db/migration'
import { actor } from 'rivetkit'
import { db } from 'rivetkit/db'
import { type Auth, authOptions, makeAuth } from './auth.ts'
import { dialectStats, type RawAccess, RivetSqliteDialect } from './rivet-dialect.ts'
import { runStoreOp, type StoreOp, stats } from './sql-store.ts'

const schemaSql = await Bun.file(new URL('../schema.sql', import.meta.url)).text()

async function userStatus(raw: RawAccess, id: string) {
  const rows = await raw.execute<{ id: string; inactive: number | null }>(`SELECT id, inactive FROM "user" WHERE id = ?`, id)
  return rows[0] ? { exists: true, inactive: Boolean(rows[0].inactive) } : { exists: false, inactive: false }
}

async function setInactive(raw: RawAccess, id: string, inactive: boolean) {
  await raw.execute(`UPDATE "user" SET inactive = ? WHERE id = ?`, inactive ? 1 : 0, id)
  // Also stop new short-lived tokens straight away: sessions and OAuth refresh
  // tokens go; already-issued JWTs ride out their 15 minutes.
  if (inactive) {
    await raw.execute(`DELETE FROM "session" WHERE "userId" = ?`, id)
    await raw.execute(`UPDATE "oauthRefreshToken" SET "revoked" = ? WHERE "userId" = ?`, new Date().toISOString(), id)
  }
}

export const directoryA = actor({
  db: db({
    onMigrate: async (database) => {
      await database.execute(`CREATE TABLE IF NOT EXISTS _migrations (name TEXT PRIMARY KEY)`)
      const done = await database.execute(`SELECT name FROM _migrations WHERE name = 'better-auth-1'`)
      if (done.length) return
      for (const stmt of schemaSql.split(/;\s*\n/).map((s) => s.trim()).filter(Boolean)) await database.execute(stmt)
      await database.execute(`INSERT INTO _migrations (name) VALUES ('better-auth-1')`)
    },
  }),
  actions: {
    store: (c, op: StoreOp) => runStoreOp(c.db, op),
    userStatus: (c, id: string) => userStatus(c.db as RawAccess, id),
    setInactive: (c, id: string, inactive: boolean) => setInactive(c.db as RawAccess, id, inactive),
    stats: () => ({ ...stats }),
    sql: (c, query: string, ...args: unknown[]) => c.db.execute(query, ...args),
  },
})

// One Better Auth instance per actor wake-up, bound to that wake-up's c.db.
function authFor(c: { db: unknown; vars: { auth: Auth | null } }): Auth {
  c.vars.auth ??= makeAuth({ dialect: new RivetSqliteDialect(c.db as RawAccess), type: 'sqlite' } as never)
  return c.vars.auth
}

export const directoryB = actor({
  db: db({
    onMigrate: async (database) => {
      const { runMigrations, toBeCreated, toBeAdded } = await getMigrations(
        authOptions({ dialect: new RivetSqliteDialect(database as RawAccess), type: 'sqlite' } as never) as never,
      )
      if (toBeCreated.length || toBeAdded.length) await runMigrations()
    },
  }),
  createVars: () => ({ auth: null as Auth | null }),
  onRequest: async (c, request) => {
    const auth = authFor(c)
    // The app node passes the public URL; the actor sees its own path.
    const original = request.headers.get('x-ideaf-url')
    const req = original ? new Request(original, request) : request
    const { pathname } = new URL(req.url)
    if (pathname === '/.well-known/oauth-authorization-server' || pathname.startsWith('/.well-known/oauth-authorization-server/'))
      return oauthProviderAuthServerMetadata(auth as never)(req)
    if (pathname === '/.well-known/openid-configuration' || pathname.startsWith('/.well-known/openid-configuration/'))
      return oauthProviderOpenIdConfigMetadata(auth as never)(req)
    if (pathname === '/ideaf/outbox') return Response.json((await import('./auth.ts')).outbox)
    if (pathname === '/ideaf/api') {
      // server-side auth.api calls from the app node (token exchange, keys)
      const { method, body, headers } = (await req.json()) as { method: string; body?: unknown; headers?: Record<string, string> }
      try {
        const fn = (auth.api as Record<string, (a: unknown) => Promise<unknown>>)[method]!
        return Response.json({ ok: true, value: await fn({ body, headers: new Headers(headers ?? {}) }) })
      } catch (e) {
        return Response.json({ ok: false, error: String((e as Error).message ?? e), status: (e as { statusCode?: number }).statusCode })
      }
    }
    return auth.handler(req)
  },
  actions: {
    userStatus: (c, id: string) => userStatus(c.db as RawAccess, id),
    setInactive: (c, id: string, inactive: boolean) => setInactive(c.db as RawAccess, id, inactive),
    stats: () => ({ statements: dialectStats.statements }),
    sql: (c, query: string, ...args: unknown[]) => c.db.execute(query, ...args),
  },
})
